CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TYPE user_role AS ENUM ('LISTENER','ARTIST','ADMIN');
CREATE TYPE release_type AS ENUM ('SINGLE','EP','ALBUM');
CREATE TYPE visibility AS ENUM ('PUBLIC','PRIVATE','UNLISTED');
CREATE TYPE subscription_status AS ENUM ('TRIALING','ACTIVE','PAST_DUE','CANCELED','EXPIRED');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email citext UNIQUE NOT NULL, password_hash text NOT NULL, username text UNIQUE NOT NULL, display_name text NOT NULL, role user_role NOT NULL DEFAULT 'LISTENER', country text, region text, language text DEFAULT 'en', timezone text DEFAULT 'UTC', explicit_allowed boolean NOT NULL DEFAULT true, avatar_url text, cover_url text, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artists (id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, bio text DEFAULT '', verified boolean NOT NULL DEFAULT false, followers_count bigint NOT NULL DEFAULT 0, monthly_listeners bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE genres (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid REFERENCES genres(id), slug text UNIQUE NOT NULL, name text NOT NULL, locale text DEFAULT 'en', active boolean NOT NULL DEFAULT true);
CREATE TABLE albums (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artist_id uuid NOT NULL REFERENCES artists(id), title text NOT NULL, release_date date, artwork_url text, genre_id uuid REFERENCES genres(id), description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE releases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artist_id uuid NOT NULL REFERENCES artists(id), title text NOT NULL, type release_type NOT NULL, release_date date, original_release_date date, artwork_url text, upc text, territory_policy jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'DRAFT', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE songs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artist_id uuid NOT NULL REFERENCES artists(id), release_id uuid REFERENCES releases(id), album_id uuid REFERENCES albums(id), title text NOT NULL, duration_ms integer NOT NULL DEFAULT 0, audio_key text, preview_key text, artwork_url text, isrc text, genre_id uuid REFERENCES genres(id), subgenre text, mood text, language text, explicit boolean NOT NULL DEFAULT false, producer text, composer text, songwriter text, label text, copyright_holder text, streams bigint NOT NULL DEFAULT 0, likes bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE playlists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, description text DEFAULT '', artwork_url text, visibility visibility NOT NULL DEFAULT 'PRIVATE', collaborative boolean NOT NULL DEFAULT false, likes bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE playlist_tracks (playlist_id uuid REFERENCES playlists(id) ON DELETE CASCADE, song_id uuid REFERENCES songs(id) ON DELETE CASCADE, position integer NOT NULL, added_by uuid REFERENCES users(id), added_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (playlist_id,song_id));
CREATE TABLE playlist_collaborators (playlist_id uuid REFERENCES playlists(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, permission text NOT NULL DEFAULT 'EDITOR', PRIMARY KEY (playlist_id,user_id));
CREATE TABLE song_likes (user_id uuid REFERENCES users(id) ON DELETE CASCADE, song_id uuid REFERENCES songs(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,song_id));
CREATE TABLE follows (follower_id uuid REFERENCES users(id) ON DELETE CASCADE, artist_id uuid REFERENCES artists(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(follower_id,artist_id));
CREATE TABLE listening_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, song_id uuid REFERENCES songs(id) ON DELETE SET NULL, session_id uuid, event_type text NOT NULL, position_ms integer, duration_ms integer, country text, region text, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX listening_events_user_time ON listening_events(user_id,occurred_at DESC); CREATE INDEX songs_artist ON songs(artist_id); CREATE INDEX playlist_tracks_position ON playlist_tracks(playlist_id,position); CREATE INDEX songs_search ON songs USING gin(to_tsvector('simple',title));
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider text, external_customer_id text, external_subscription_id text, plan text NOT NULL DEFAULT 'PREMIUM', status subscription_status NOT NULL DEFAULT 'TRIALING', trial_ends_at timestamptz, current_period_end timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type text NOT NULL, title text NOT NULL, body text NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), release_id uuid REFERENCES releases(id) ON DELETE CASCADE, song_id uuid REFERENCES songs(id) ON DELETE CASCADE, master_owner text, publishing_owner text, distributor text, territories text[] NOT NULL DEFAULT '{}', license_status text NOT NULL DEFAULT 'PENDING', isrc text, upc text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid REFERENCES users(id) ON DELETE SET NULL, target_type text NOT NULL, target_id uuid NOT NULL, reason text NOT NULL, details text, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, target_type text, target_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
